# Look specifically for verdict from the system/server (not my own code)
import json
import os

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
session_file = d+'/../../sessions/'+os.path.basename(d)+'.jsonl'

with open(session_file, 'r') as f:
    content = f.read()

# Parse messages to find verdict相关内容 (verdict related entries)
for line in content.strip().split('\n'):
    if line.strip():
        try:
            msg = json.loads(line)
            msg_type = msg.get('type', '')

            # Look for verdict-like messages
            if msg_type == 'message':
                text = msg.get('message', {}).get('content', [])
                for item in text:
                    if isinstance(item, dict) and 'text' in item:
                        txt = item['text']
                        if 'Verdict' in txt or 'Correct' in txt or 'Wrong' in txt or 'SUBMIT' in txt:
                            print("Found potential verdict message:")
                            print(txt[:500] + "..." if len(txt) > 500 else txt)
                            print("---")
        except:
            pass

# Also look for verdict in stdout from tools
print("\n\nLooking for verdict in tool outputs...")
for line in content.strip().split('\n'):
    if line.strip() and 'ipython' in line.lower():
        try:
            msg = json.loads(line)
            if msg.get('type') == 'toolResult':
                content_type = msg.get('content', [])
                for item in content_type:
                    if isinstance(item, dict) and 'text' in item:
                        txt = item['text']
                        if 'verdict' in txt.lower() or 'wrong' in txt.lower() or 'correct' in txt.lower():
                            print("Found:")
                            print(txt[:500])
        except:
            pass

